#include <iostream>
using namespace std;
int main() {
    int x = 26;
    cout << dec << x << endl;  // 26（十进制）
    cout << hex << x << endl;  // 1a（十六进制）
    cout << oct << x << endl;  // 32（八进制）
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int a = 5, b = 3;          // 0101 和 0011
    cout << (a & b) << endl;   // 1
    cout << (a | b) << endl;   // 7
    cout << (a ^ b) << endl;   // 6
    cout << (1 << 4) << endl;  // 16：1 左移 4 位 = ×16
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int n, a[105], mx = -1000000000;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++)
        if (a[i] > mx) mx = a[i];
    cout << mx << endl;   // 输出最大值
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;
int main() {
    string s = "Hello";
    cout << s.size() << endl;          // 5
    cout << s[0] << endl;              // H
    cout << s.find("llo") << endl;     // 2
    cout << s.substr(1, 3) << endl;    // ell
    cout << (char)toupper('a') << endl; // A
    return 0;
}

